+        background: var(--surface);
+        box-shadow: var(--shadow);
+      }
+
+      h1 {
+        margin: 0 0 0.75rem;
+        font-size: clamp(2rem, 7vw, 3rem);
+        line-height: 1;
+        letter-spacing: -0.06em;
+      }
+
+      .lede {
+        margin: 0 0 2rem;
+        color: var(--muted);
+      }
+
+      form {
+        display: grid;
+        gap: 1.25rem;
+      }
+
+      .form-field {
+        display: grid;
+        grid-template-columns: auto 1fr;
+        gap: 0.25rem 0.8rem;
+        align-items: start;
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+        padding: 1rem;
+        background: #fbfdff;
+      }
+
+      .form-field:focus-within {
+        border-color: var(--primary);
+        box-shadow: 0 0 0 4px #2457d61f;
+      }
+
+      input[type="checkbox"] {
+        width: 1.25rem;
+        height: 1.25rem;
+        margin: 0.15rem 0 0;
+        accent-color: var(--primary);
+      }
+
+      label {
+        font-weight: 700;
+      }
+
+      .helper-text {
+        grid-column: 2;
+        margin: 0;
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
+      button {
+        min-height: 3rem;
+        border: 0;
+        border-radius: 999px;
+        padding: 0.8rem 1.25rem;
+        color: #ffffff;
+        background: var(--primary);
+        font: inherit;
+        font-weight: 800;
+        cursor: pointer;
+        transition:
+          background-color 160ms ease,
+          transform 160ms ease;
+      }
+
+      button:hover {
+        background: var(--primary-dark);
+      }
+
+      button:active {
+        transform: translateY(1px);
+      }
+
+      :focus-visible {
+        outline: 3px solid var(--focus);
+        outline-offset: 3px;
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 0;
+        color: var(--success);
+        font-weight: 700;
+      }
+
