+        <h1 id="page-title">Create your account</h1>
+        <p class="lede">Review and accept the terms to continue.</p>
+
+        <form id="consent-form" novalidate>
+          <div class="form-field">
+            <input
+              type="checkbox"
+              id="terms"
+              name="terms"
+              required
+              aria-describedby="terms-helper terms-error"
+            >
+            <label for="terms">I agree to the terms of use</label>
+            <p class="helper-text" id="terms-helper">
+              Required to create an account and use this service.
+            </p>
+            <p class="helper-text" id="terms-error" aria-live="polite"></p>
+          </div>
+
+          <button type="submit">Submit</button>
+          <p class="status" id="form-status" role="status" aria-live="polite"></p>
+        </form>
+      </section>
+    </main>
+
+    <script>
+      const form = document.querySelector("#consent-form");
+      const terms = document.querySelector("#terms");
+      const error = document.querySelector("#terms-error");
+      const status = document.querySelector("#form-status");
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+
+        if (!terms.checked) {
+          terms.setAttribute("aria-invalid", "true");
